import{_ as a,o,c as l,aw as s}from"./chunks/framework.DLufY-ao.js";const i="/workbook/assets/promise-state.C0iQbLym.png",u=JSON.parse('{"title":"Информация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-promise/main/info.md","filePath":"wiki/dev-commit/js/js-promise/main/info.md"}'),t={name:"wiki/dev-commit/js/js-promise/main/info.md"};function r(n,e,c,d,h,p){return o(),l("div",null,[...e[0]||(e[0]=[s('<h1 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h1><h2 id="информация-1" tabindex="-1">Информация <a class="header-anchor" href="#информация-1" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://www.youtube.com/watch?v=1idOY3C1gYU" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=1idOY3C1gYU</a> - YouTube</li><li><a href="https://dev.to/lydiahallie/javascript-visualized-promises-async-await-5gke" target="_blank" rel="noreferrer">https://dev.to/lydiahallie/javascript-visualized-promises-async-await-5gke</a> - JavaScript Visualized: Promises &amp; Async/Await</li></ul></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Promise</strong> - специальный объект, который используются для обработки результатов асинхронных операций. Промис хранит своё состояние, текущий результат (если есть) и коллбэки</li><li><strong>Промисификация</strong> - обертка над асинхронным функционалом, возвращающая промис</li><li><strong>Чейнинг (chaining)</strong> - возможность стоить асинхронные цепочки из промисов .then…then…then, в каждый следующий then переходит результат от предыдущего</li></ul></div><h2 id="способ-использования" tabindex="-1">Способ использования <a class="header-anchor" href="#способ-использования" aria-label="Permalink to &quot;Способ использования&quot;">​</a></h2><ol><li>Код, которому нужно сделать что-то асинхронно, создаёт экземпляр объекта через <code>new Promise</code> и возвращает его</li><li>При создании <code>new Promise</code> автоматически запускается функция-аргумент, которая должна вызвать <code>resolve(result)</code> при успешном выполнении и <code>reject(error)</code> - при ошибке</li><li>Внешний код, получив promise, навешивает на него обработчики <code>.then</code> и <code>.catch</code></li><li>По завершении процесса асинхронный код переводит promise в состояние <strong>fulfilled</strong> (с результатом) или <strong>rejected</strong> (с ошибкой). При этом автоматически вызываются соответствующие обработчики во внешнем коде <code>.then</code> и <code>.catch</code></li></ol><h2 id="состояния-и-коллбэки" tabindex="-1">Состояния и коллбэки <a class="header-anchor" href="#состояния-и-коллбэки" aria-label="Permalink to &quot;Состояния и коллбэки&quot;">​</a></h2><h3 id="состояния" tabindex="-1">Состояния <a class="header-anchor" href="#состояния" aria-label="Permalink to &quot;Состояния&quot;">​</a></h3><ol><li><strong>pending</strong> - ожидание (выполняется)</li><li><strong>fulfilled</strong> - выполнено успешно</li><li><strong>rejected</strong> - отклонено (выполнено с ошибкой)</li></ol><h3 id="навешиваемые-коллбэки" tabindex="-1">Навешиваемые коллбэки <a class="header-anchor" href="#навешиваемые-коллбэки" aria-label="Permalink to &quot;Навешиваемые коллбэки&quot;">​</a></h3><ul><li><code>onFulfilled</code> – срабатывают, когда promise в состоянии fulfilled</li><li><code>onRejected</code> – срабатывают, когда promise в состоянии rejected</li></ul><img src="'+i+`"><h3 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">let</span><span style="color:#383A42;"> promise </span><span style="color:#0184BC;">=</span><span style="color:#A626A4;"> new</span><span style="color:#C18401;"> Promise</span><span style="color:#383A42;">(</span><span style="color:#A626A4;">function</span><span style="color:#383A42;"> (resolve, reject) {</span></span>
<span class="line"><span style="color:#4078F2;">  resolve</span><span style="color:#383A42;">(arg); </span><span style="color:#A0A1A7;font-style:italic;">// =&gt; onFulfilled(arg) =&gt; .then(arg)  =&gt; Promise</span></span>
<span class="line"><span style="color:#4078F2;">  reject</span><span style="color:#383A42;">(arg); </span><span style="color:#A0A1A7;font-style:italic;">// =&gt; onRejected(arg)  =&gt; .catch(arg) =&gt; Promise</span></span>
<span class="line"><span style="color:#383A42;">});</span></span></code></pre></div><h2 id="категории" tabindex="-1">Категории <a class="header-anchor" href="#категории" aria-label="Permalink to &quot;Категории&quot;">​</a></h2><h3 id="минусы-промисов" tabindex="-1">Минусы промисов <a class="header-anchor" href="#минусы-промисов" aria-label="Permalink to &quot;Минусы промисов&quot;">​</a></h3><ul><li>Нельзя отменить</li><li>Метод <code>finally</code> не особо кроссбраузерный</li></ul><h3 id="использование-метода-finally" tabindex="-1">Использование метода finally <a class="header-anchor" href="#использование-метода-finally" aria-label="Permalink to &quot;Использование метода finally&quot;">​</a></h3><ul><li>finally не меняет состояние промиса</li><li><em>Пример использования</em>: скрыть лоадер (неважно ошибка или успешно)</li></ul><h3 id="комментарии" tabindex="-1">Комментарии <a class="header-anchor" href="#комментарии" aria-label="Permalink to &quot;Комментарии&quot;">​</a></h3><ul><li>При взаимодействии с API <code>catch</code> используется для обработки <em>http статусов 4xx 5xx</em>, <code>then</code> это статусы <em>2xx</em></li><li>Состояние промиса изменяется 1 раз</li><li>Promise после <code>reject</code>/<code>resolve</code> - неизменны</li><li>Отсутствие внешнего <code>catch</code> не останавливает выполнение скрипта. Когда обработчик в промисах делает <code>throw</code> - в данном случае, при ошибке запроса, то такая ошибка не останавливает выполнение скрипта и не выводится в консоли. Она просто будет передана в ближайший следующий обработчик <code>onRejected</code>.</li></ul>`,21)])])}const f=a(t,[["render",r]]);export{u as __pageData,f as default};
